1	package com.example.starter.api;
2	
3	import com.example.starter.api.dto.ArtifactResponse;
4	import com.example.starter.api.dto.DependencySpec;
5	import com.example.starter.api.dto.LockFileResponse;
6	import com.example.starter.api.dto.LockRequest;
7	import com.example.starter.api.dto.RegisterArtifactRequest;
8	import com.example.starter.support.ApiException;
9	import org.junit.jupiter.api.BeforeEach;
10	import org.junit.jupiter.api.Test;
11	import org.springframework.beans.factory.annotation.Autowired;
12	import org.springframework.boot.test.context.SpringBootTest;
13	import org.springframework.jdbc.core.JdbcTemplate;
14	
15	import java.util.ArrayList;
16	import java.util.List;
17	import java.util.UUID;
18	import java.util.concurrent.Callable;
19	import java.util.concurrent.CyclicBarrier;
20	import java.util.concurrent.ExecutorService;
21	import java.util.concurrent.Executors;
22	import java.util.concurrent.Future;
23	import java.util.concurrent.TimeUnit;
24	
25	import static org.assertj.core.api.Assertions.assertThat;
26	import static org.assertj.core.api.Assertions.assertThatThrownBy;
27	import static org.assertj.core.api.Assertions.tuple;
28	
29	/**
30	 * 基于嵌入式 H2（MODE=MySQL）的服务层数据库与业务测试：
31	 * 覆盖主流程、失败分支、幂等重放、事务回滚以及锁定/撤回/幂等的真实并发边界。
32	 */
33	@SpringBootTest
34	class ArtifactServiceH2Test {
35	
36	    @Autowired
37	    private ArtifactService service;
38	
39	    @Autowired
40	    private JdbcTemplate jdbcTemplate;
41	
42	    @BeforeEach
43	    void cleanDatabase() {
44	        jdbcTemplate.update("DELETE FROM lock_file_entry");
45	        jdbcTemplate.update("DELETE FROM lock_file");
46	        jdbcTemplate.update("DELETE FROM artifact_dependency");
47	        jdbcTemplate.update("DELETE FROM artifact");
48	        jdbcTemplate.update("DELETE FROM idempotent_request");
49	        jdbcTemplate.update("UPDATE repository_state SET version = 0 WHERE id = 1");
50	    }
51	
52	    private static String requestId() {
53	        return UUID.randomUUID().toString();
54	    }
55	
56	    private RegisterArtifactRequest artifact(String name, int version, DependencySpec... deps) {
57	        return new RegisterArtifactRequest(name, version, List.of(deps));
58	    }
59	
60	    private static DependencySpec dep(String name, int min, int max) {
61	        return new DependencySpec(name, min, max);
62	    }
63	
64	    // ------------------------------------------------------------------
65	    // 主流程
66	    // ------------------------------------------------------------------
67	
68	    @Test
69	    void registerIncrementsRepositoryVersionAndPersistsDependencies() {
70	        ArtifactResponse a1 = service.registerArtifact(requestId(),
71	                artifact("app", 1, dep("lib", 1, 2)));
72	        assertThat(a1.repositoryVersion()).isEqualTo(1);
73	        assertThat(a1.withdrawn()).isFalse();
74	        assertThat(a1.dependencies()).extracting("name", "minimumVersion", "maximumVersion")
75	                .containsExactly(tuple("lib", 1, 2));
76	
77	        ArtifactResponse a2 = service.registerArtifact(requestId(),
78	                artifact("lib", 2));
79	        assertThat(a2.repositoryVersion()).isEqualTo(2);
80	    }
81	
82	    @Test
83	    void lockProducesSortedEntriesAndPersistsRepositoryVersion() {
84	        // app:1 -> lib[1,2] 且 util[1,1]；lib2/lib1 均在，取高版本 lib2。
85	        service.registerArtifact(requestId(),
86	                artifact("app", 1, dep("util", 1, 1), dep("lib", 1, 2)));
87	        service.registerArtifact(requestId(), artifact("lib", 2));
88	        service.registerArtifact(requestId(), artifact("lib", 1));
89	        service.registerArtifact(requestId(), artifact("util", 1));
90	
91	        LockFileResponse lock = service.createLock(requestId(), new LockRequest("app", 1, 4L));
92	
93	        assertThat(lock.repositoryVersion()).isEqualTo(4L);
94	        assertThat(lock.rootName()).isEqualTo("app");
95	        assertThat(lock.rootVersion()).isEqualTo(1);
96	        assertThat(lock.entries()).extracting("name", "version")
97	                .containsExactly(tuple("app", 1), tuple("lib", 2), tuple("util", 1));
98	
99	        // 历史查询：列表与单查一致，条目按名称升序。
100	        List<LockFileResponse> locks = service.listLocks();
101	        assertThat(locks).hasSize(1);
102	        assertThat(service.getLock(lock.id()).entries()).isEqualTo(lock.entries());
103	    }
104	
105	    @Test
106	    void lockWithdrawConflictConcurrencyLeavesQueryableLock() throws Exception {
107	        // 串行准备：app:1 -> lib[1,1]，lib:1；当前仓库版本为 2。
108	        service.registerArtifact(requestId(), artifact("app", 1, dep("lib", 1, 1)));
109	        service.registerArtifact(requestId(), artifact("lib", 1));
110	        long versionBefore = 2L;
111	
112	        ExecutorService pool = Executors.newFixedThreadPool(2);
113	        CyclicBarrier barrier = new CyclicBarrier(2);
114	        String lockRequestId = requestId();
115	        String withdrawRequestId = requestId();
116	
117	        Callable<Object> lockTask = () -> {
118	            barrier.await(5, TimeUnit.SECONDS);
119	            try {
120	                return service.createLock(lockRequestId,
121	                        new LockRequest("app", 1, versionBefore));
122	            } catch (ApiException e) {
123	                return e;
124	            }
125	        };
126	        Callable<Object> withdrawTask = () -> {
127	            barrier.await(5, TimeUnit.SECONDS);
128	            return service.withdrawArtifact(withdrawRequestId, "lib", 1);
129	        };
130	
131	        List<Future<Object>> futures = pool.invokeAll(List.of(lockTask, withdrawTask));
132	        pool.shutdown();
133	        Object lockOutcome = futures.get(0).get(30, TimeUnit.SECONDS);
134	        Object withdrawOutcome = futures.get(1).get(30, TimeUnit.SECONDS);
135	
136	        assertThat(withdrawOutcome).isInstanceOf(ArtifactResponse.class);
137	        long finalVersion = jdbcTemplate.queryForObject(
138	                "SELECT version FROM repository_state WHERE id = 1", Long.class);
139	        assertThat(finalVersion).isEqualTo(versionBefore + 1);
140	
141	        if (lockOutcome instanceof LockFileResponse lock) {
142	            // 锁先提交：即使 lib 后被撤回，锁文件仍可查询、内容不改写。
143	            assertThat(lock.entries()).extracting("name", "version")
144	                    .containsExactly(tuple("app", 1), tuple("lib", 1));
145	            LockFileResponse queried = service.getLock(lock.id());
146	            assertThat(queried.repositoryVersion()).isEqualTo(versionBefore);
147	            assertThat(queried.entries()).isEqualTo(lock.entries());
148	        } else {
149	            // 撤回先提交：期望版本过期，锁必须 409，且无半成品。
150	            assertThat(lockOutcome).isInstanceOf(ApiException.class);
151	            assertThat(((ApiException) lockOutcome).getStatus()).isEqualTo(409);
152	            assertThat(service.listLocks()).isEmpty();
153	        }
154	    }
155	
156	    // ------------------------------------------------------------------
157	    // 失败分支
158	    // ------------------------------------------------------------------
159	
160	    @Test
161	    void duplicateArtifactVersionReturns409() {
162	        service.registerArtifact(requestId(), artifact("app", 1));
163	        assertThatThrownBy(() -> service.registerArtifact(requestId(), artifact("app", 1)))
164	                .isInstanceOfSatisfying(ApiException.class,
165	                        e -> assertThat(e.getStatus()).isEqualTo(409));
166	    }
167	
168	    @Test
169	    void withdrawMissingArtifactReturns404() {
170	        assertThatThrownBy(() -> service.withdrawArtifact(requestId(), "ghost", 9))
171	                .isInstanceOfSatisfying(ApiException.class,
172	                        e -> assertThat(e.getStatus()).isEqualTo(404));
173	    }
174	
175	    @Test
176	    void doubleWithdrawReturns409AndSecondWithdrawConsumesNoKey() {
177	        service.registerArtifact(requestId(), artifact("app", 1));
178	        service.withdrawArtifact(requestId(), "app", 1);
179	        long versionAfterFirstWithdraw = jdbcTemplate.queryForObject(
180	                "SELECT version FROM repository_state WHERE id = 1", Long.class);
181	
182	        assertThatThrownBy(() -> service.withdrawArtifact(requestId(), "app", 1))
183	                .isInstanceOfSatisfying(ApiException.class,
184	                        e -> assertThat(e.getStatus()).isEqualTo(409));
185	        assertThat(jdbcTemplate.queryForObject(
186	                "SELECT version FROM repository_state WHERE id = 1", Long.class))
187	                .isEqualTo(versionAfterFirstWithdraw);
188	    }
189	
190	    @Test
191	    void lockWithStaleExpectedRepositoryVersionReturns409WithoutSaving() {
192	        service.registerArtifact(requestId(), artifact("app", 1));
193	        assertThatThrownBy(() -> service.createLock(requestId(), new LockRequest("app", 1, 0L)))
194	                .isInstanceOfSatisfying(ApiException.class,
195	                        e -> assertThat(e.getStatus()).isEqualTo(409));
196	        assertThat(service.listLocks()).isEmpty();
197	        assertThat(jdbcTemplate.queryForObject("SELECT COUNT(1) FROM lock_file_entry", Integer.class))
198	                .isZero();
199	    }
200	
201	    @Test
202	    void lockOnWithdrawnRootReturns409() {
203	        service.registerArtifact(requestId(), artifact("app", 1));
204	        service.withdrawArtifact(requestId(), "app", 1);
205	        assertThatThrownBy(() -> service.createLock(requestId(), new LockRequest("app", 1, 2L)))
206	                .isInstanceOfSatisfying(ApiException.class,
207	                        e -> assertThat(e.getStatus()).isEqualTo(409));
208	    }
209	
210	    @Test
